import{_ as n,C as r,o as s,c,j as e,a as d,E as o,a5 as l}from"./chunks/framework.Dep_XxFZ.js";const P=JSON.parse('{"title":"切换按钮","description":"","frontmatter":{},"headers":[],"relativePath":"components/toggle.md","filePath":"components/toggle.md","lastUpdated":1787173379000}'),h={name:"components/toggle.md"},b={id:"切换按钮",tabindex:"-1"};function g(p,t,u,x,f,m){const i=r("Badge"),a=r("XhDemo");return s(),c("div",null,[e("h1",b,[t[0]||(t[0]=d("切换按钮 ",-1)),o(i,{type:"info",text:"toggle"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#切换按钮","aria-label":'Permalink to "切换按钮 <Badge type="info" text="toggle" />"'},"​",-1))]),t[3]||(t[3]=l('<p>一颗有记忆的按钮：按下去留在按下态，再按一下弹回来。状态由 <code>aria-pressed</code> 表达。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>开关一项立即生效的格式或视图（加粗、显示网格、静音）。</li><li>状态属于工具而不属于表单：它不参与表单提交。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>表示一项设置的开与关、且要随表单提交：用<a href="./switch">开关</a>或<a href="./checkbox">复选框</a>。</li><li>几个选项互斥：用<a href="./toggle-group">切换按钮组</a>——多个独立的切换按钮各管各的按下态，凑不出互斥。</li><li>按下去只发生一次动作、不留状态：那是<a href="./button">按钮</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>形态 · 语气 · 尺寸三轴与按钮同源。</li><li>受控时宿主不写回 <code>pressed</code> 值就不动，在途期间来的意图直接丢掉。</li><li><code>disabled</code> 同时挡住指针与键盘，按下态保持原样。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>按下态由 pressed 表达，非受控时组件自己维护</p>',10)),o(a,{src:"toggle/01-basic"}),t[4]||(t[4]=e("h3",{id:"禁用",tabindex:"-1"},[d("禁用 "),e("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),t[5]||(t[5]=e("p",null,"disabled 同时挡住指针与键盘，按下态保持原样",-1)),o(a,{src:"toggle/02-disabled"}),t[6]||(t[6]=e("h3",{id:"排成一组",tabindex:"-1"},[d("排成一组 "),e("a",{class:"header-anchor",href:"#排成一组","aria-label":'Permalink to "排成一组"'},"​")],-1)),t[7]||(t[7]=e("p",null,"多个独立的 toggle 各管各的按下态；要互斥或单一 Tab 位请改用切换按钮组",-1)),o(a,{src:"toggle/03-group"}),t[8]||(t[8]=e("h3",{id:"形态",tabindex:"-1"},[d("形态 "),e("a",{class:"header-anchor",href:"#形态","aria-label":'Permalink to "形态"'},"​")],-1)),t[9]||(t[9]=e("p",null,"variant 决定颜色怎么用，未按下与已按下两档一起看才完整",-1)),o(a,{src:"toggle/04-variant"}),t[10]||(t[10]=e("h3",{id:"语气",tabindex:"-1"},[d("语气 "),e("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[11]||(t[11]=e("p",null,"tone 决定用哪族颜色，与 variant 正交；这里固定 solid 形态并置于按下态，语气差别最明显",-1)),o(a,{src:"toggle/05-tone"}),t[12]||(t[12]=e("h3",{id:"尺寸",tabindex:"-1"},[d("尺寸 "),e("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[13]||(t[13]=e("p",null,"size 只改高度、内边距与字号，不写就是缺省档",-1)),o(a,{src:"toggle/06-size"}),t[14]||(t[14]=e("h3",{id:"图标",tabindex:"-1"},[d("图标 "),e("a",{class:"header-anchor",href:"#图标","aria-label":'Permalink to "图标"'},"​")],-1)),t[15]||(t[15]=e("p",null,"按钮内容随便写，图标与文字之间的空隙由 --xh-toggle-gap 给；只放图标时按钮没有可见文字，名字得由 aria-label 补上",-1)),o(a,{src:"toggle/07-icon"}),t[16]||(t[16]=e("h3",{id:"变化回调",tabindex:"-1"},[d("变化回调 "),e("a",{class:"header-anchor",href:"#变化回调","aria-label":'Permalink to "变化回调"'},"​")],-1)),t[17]||(t[17]=e("p",null,"pressed-change 每次带着 details 报一次按下意图；不做受控绑定时它就是拿到新值的唯一出口",-1)),o(a,{src:"toggle/08-events"}),t[18]||(t[18]=e("h3",{id:"请求在途",tabindex:"-1"},[d("请求在途 "),e("a",{class:"header-anchor",href:"#请求在途","aria-label":'Permalink to "请求在途"'},"​")],-1)),t[19]||(t[19]=e("p",null,"受控的 pressed 不写回就不会动，在途期间来的意图直接丢掉；忙碌反馈由 aria-busy 与一枚转圈补在按钮上",-1)),o(a,{src:"toggle/09-pending"}),t[20]||(t[20]=l('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-toggle&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhToggle</code></td></tr><tr><td>组合式函数</td><td><code>useToggle</code></td></tr><tr><td>状态机</td><td><code>toggleMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/toggle.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;toggle&quot;</code>：<strong><code>root</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>pressed</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>defaultPressed</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td></td></tr><tr><td><code>variant</code></td><td><code>ActionVariant</code></td><td></td><td>形态：solid / subtle / outline / ghost，决定颜色怎么用</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg</td></tr><tr><td><code>onPressedChange</code></td><td><code>(details: TogglePressedChangeDetails) =&gt; void</code></td><td></td><td>pressed 变化意图回调；受控时是唯一出口，非受控随内部转移一并通知。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>pressed-change</code></td><td><code>TogglePressedChangeDetails</code></td><td>pressed 状态变化；detail 为 <code>{ pressed: boolean }</code></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;on&#39; | &#39;off&#39;</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>off</code> · <code>on</code></p><p><strong>事件</strong>：<code>TOGGLE</code> · <code>CONTROLLED.ON</code> · <code>CONTROLLED.OFF</code></p><p><strong>判据</strong>：<code>isPressedControlled</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useToggle</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>pressed</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>setPressed</code></td><td><code>(next: boolean) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/button/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Space</code> / <code>Enter</code></td><td>focus in root, not disabled</td><td>切换 pressed 状态</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-pressed</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/toggle.css</code> 按部件选择：<code>[data-scope=&quot;toggle&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;on&#39; | &#39;off&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-toggle-bg</code> · <code>--xh-toggle-bg-hover</code> · <code>--xh-toggle-bg-pressed</code> · <code>--xh-toggle-fg</code> · <code>--xh-toggle-fg-pressed</code> · <code>--xh-toggle-font-size</code> · <code>--xh-toggle-font-weight</code> · <code>--xh-toggle-gap</code> · <code>--xh-toggle-h</code> · <code>--xh-toggle-px</code> · <code>--xh-toggle-radius</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>排成一条工具条：外面套<a href="./toolbar">工具栏</a>拿到方向键导航。</li><li>只放图标时配<a href="./tooltip">文字提示</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>只放图标时给 <code>aria-label</code>，名字不能靠图形猜。</li><li>按下与未按下的差别要能在灰度下看出来，别只靠颜色。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用它表达&quot;当前在哪个标签页&quot;：那是<a href="./tabs">标签页</a>的事。</li><li>请求在途时让按钮先翻状态再回滚：受控绑定不写回，用户看到的就是稳定的。</li></ul>',45))])}const k=n(h,[["render",g]]);export{P as __pageData,k as default};
